import {entryFor,artworkFor} from './tierlist-model.mjs?v=bonobean1';
const name=f=>typeof f.name==='string'?f.name:f.name.en||f.name.zh;
export async function drawTierlist(canvas,state,units){const chart=state.view==='chart',width=1000,tile=80,cols=Math.floor((width-130)/tile),heights=state.rows.map(r=>Math.max(tile,Math.ceil(r.units.length/cols)*tile));canvas.width=width;canvas.height=chart?650:110+heights.reduce((a,b)=>a+b,0)+70;const ctx=canvas.getContext('2d'),bg=state.background||'#fffef1',ink=parseInt(bg.slice(1,3),16)*.299+parseInt(bg.slice(3,5),16)*.587+parseInt(bg.slice(5,7),16)*.114<140?'#fffef1':'#282625';await document.fonts.ready;ctx.fillStyle=state.background||'#fffef1';ctx.fillRect(0,0,width,canvas.height);ctx.fillStyle=ink;ctx.font='600 28px Poppins';ctx.fillText(state.title.slice(0,55),24,43);ctx.font='16px Poppins';ctx.fillText((chart?'Alignment chart':'Tierlist')+(state.shareAuthor?' · '+state.shareAuthor:''),24,77);async function portrait(key,x,y,size=48){const e=entryFor(units,key,state.tier);if(!e)return;const img=new Image();img.src=new URL('./'+artworkFor(e,state.imageStyle),import.meta.url);try{await img.decode();const scale=Math.min(size/img.naturalWidth,size/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;ctx.drawImage(img,x+(size-w)/2,y+(size-h)/2,w,h)}catch{throw Error('Could not load Tatari artwork. Try exporting again.')}}let y=110;if(chart){const left=90,top=130,chartWidth=820,chartHeight=440;ctx.strokeStyle='#575452';ctx.strokeRect(left,top,chartWidth,chartHeight);ctx.beginPath();ctx.moveTo(left+chartWidth/2,top);ctx.lineTo(left+chartWidth/2,top+chartHeight);ctx.moveTo(left,top+chartHeight/2);ctx.lineTo(left+chartWidth,top+chartHeight/2);ctx.stroke();ctx.font='14px Poppins';ctx.textAlign='center';ctx.fillText(state.chart.top,500,115);ctx.fillText(state.chart.bottom,500,615);ctx.save();ctx.translate(30,350);ctx.rotate(-Math.PI/2);ctx.fillText(state.chart.left,0,0);ctx.restore();ctx.save();ctx.translate(970,350);ctx.rotate(Math.PI/2);ctx.fillText(state.chart.right,0,0);ctx.restore();ctx.textAlign='left';for(const [key,p] of Object.entries(state.chart.positions))await portrait(key,left+p.x/100*chartWidth-24,top+p.y/100*chartHeight-24);return canvas}for(const [i,row] of state.rows.entries()){ctx.fillStyle=row.color;ctx.fillRect(0,y,130,heights[i]);ctx.fillStyle='#282625';ctx.font='600 20px Poppins';ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';const lines=row.label.split(/\n/),lineHeight=26;for(const [lineIndex,line] of lines.entries())ctx.fillText(line,65,y+heights[i]/2+(lineIndex-(lines.length-1)/2)*lineHeight,114);ctx.restore();ctx.strokeStyle='#575452';ctx.strokeRect(130,y,width-130,heights[i]);for(const [j,id] of row.units.entries())await portrait(id,130+(j%cols)*tile,y+Math.floor(j/cols)*tile,tile);y+=heights[i]}ctx.fillStyle=ink;ctx.font='13px Poppins';ctx.fillText('Creator opinion · Clash of Critters Unofficial Companion',24,y+36);return canvas}
